(()=>{'use strict';const $=id=>document.getElementById(id),host=$('transfer-bench-lab');if(!host)return;const motion=matchMedia('(prefers-reduced-motion: reduce)');let running=false;
window.BookSources=Object.assign(window.BookSources||{},{'transfer-bench-lab':{title:'独立视线的平均透射与有效光深',pages:'690–695',pdf:'712–717',section:'MBW §16.1 · 原创双通道教学类比',body:'原书介绍吸收、透射和有效光深。此装置以两个校准独立非相干通道实现加权纯吸收，输出在探测后数值相加；不是两个串联吸收池，也不是望远镜工程图。结构和光路为原创示意。'}});
const fmt=x=>x!==0&&x<.0001?x.toExponential(4):x.toLocaleString('zh-CN',{minimumFractionDigits:5,maximumFractionDigits:5});
function render(){const tau=10**+$('transfer-tau').value,f=+$('transfer-cover').value,r=AdvancedPhysics.evaluate('transmission',{tau:+$('transfer-tau').value,cover:f}),a=f*Math.exp(-tau),b=(1-f)*Math.exp(-.1),sum=a+b;
 $('transfer-tau-value').textContent=(+$('transfer-tau').value).toFixed(2)+' · τ='+fmt(tau);$('transfer-cover-value').textContent=f.toFixed(2);$('transfer-a').textContent=fmt(a);$('transfer-b').textContent=fmt(b);$('transfer-total').textContent=fmt(sum);$('transfer-effective').textContent=fmt(r.values[1]);
 for(const [name,weight,trans]of [['variable',f,Math.exp(-tau)],['fixed',1-f,Math.exp(-.1)]]){for(const part of ['in','through','out']){const el=host.querySelector(`[data-transfer-part="beam-${name}-${part}"]`);el.style.opacity=String(part==='in'?weight:weight*trans);}const detector=host.querySelector(`[data-transfer-part="detector-${name}"]`);detector.style.setProperty('--signal',weight*trans);detector.style.filter=`brightness(${.7+.6*weight*trans})`;}
 $('transfer-result').textContent=`两路输出相加 ${fmt(a)} + ${fmt(b)} = ${fmt(sum)}。有效光深 ${fmt(r.values[1])} ≤ 平均光深 ${fmt(r.values[2])}。${f===0?'可调通道权重为零；改变它的光深不改变总信号。':f===1?'固定通道权重为零；有效光深等于可调通道光深。':'透射先求平均后取对数，与光深直接平均通常不同。'} 光路亮度仅作定性提示，定量结果以读数为准。`;
 host.dataset.total=sum;host.dataset.effective=r.values[1];document.dispatchEvent(new CustomEvent('lab:render',{detail:{id:host.id}}));}
function stop(){running=false;host.removeAttribute('data-flow');$('transfer-play').textContent='播放光路提示';$('transfer-play').setAttribute('aria-pressed','false');}
for(const id of ['transfer-tau','transfer-cover'])$(id).addEventListener('input',render);$('transfer-play').onclick=()=>{if(running||motion.matches){stop();return;}running=true;host.setAttribute('data-flow','');$('transfer-play').textContent='暂停光路提示';$('transfer-play').setAttribute('aria-pressed','true');};$('transfer-reset').onclick=()=>{stop();$('transfer-tau').value=0;$('transfer-cover').value=.5;render();};
$('transfer-question').onclick=()=>window.showTutor(`第16章独立双通道吸收：τ=${10**+$('transfer-tau').value}，f=${$('transfer-cover').value}，另一通道τ=0.1。请计算f exp(-τ)+(1-f)exp(-0.1)及有效光深，并用Jensen不等式解释有效光深不大于平均光深；区分空间混合与串联吸收。`);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});motion.addEventListener('change',()=>{if(motion.matches)stop();});document.addEventListener('reader:pagechange',()=>{if(!host.closest('.reader-slide')?.classList.contains('is-active'))stop();});new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)stop();})).observe(host);render();
})();
